enum class BSDFEvent : uint32_t
{
    None         = 0,
    Diffuse      = 1 << 0,
    Glossy       = 1 << 1,
    Delta        = 1 << 2,
    Reflection   = 1 << 3,
    Transmission = 1 << 4
};

struct BSDFSample
{
    Vec3 Wi;

    Color F;

    // Directional density in sr^-1 for continuous lobes.
    // For delta events this field follows the renderer's
    // chosen discrete/delta convention.
    float Pdf = 0.0f;

    BSDFEvent Event =
        BSDFEvent::None;

    float Eta = 1.0f;

    [[nodiscard]]
    bool IsDelta() const
    {
        return HasFlag(
            Event,
            BSDFEvent::Delta);
    }
};

struct LightSample
{
